// SPDX-License-Identifier: Apache-2.0
// Host test of the adc.phys.<NAME> / adc.qlf.<NAME> targets in the generated RteConfig.cpp (IO-18): one conversion
// per channel feeds value and quality, the integer conversion of bsp/adc/analogSensorConfiguration.h (generated by
// tools/bswgen for the test profile testproject_full, PLAT-62) gives the signed physical value, the quality is
// QLF_OK,
// QLF_ERROR_RANGE at the ends (value still copied) or QLF_ERROR when the conversion fails (value held).
// ECU: test/sensor_host/rte.yaml, component SensorSwc. Expected values: tools/nxconfig/sensor.py evaluate() for the
// same raw codes (test_rtegen.py checks the numbers used here against it).
// Build and run: tools/rtegen/test_rtegen.py (RteSensorHostTest).

#include "HostStubs.h"
#include "RteConfig.h"
#include "RteTasks.h"
#include "Rte_Internal.h"

#include <cstdio>

extern "C"
{
#include "SensorSwc.h"
}

bool bios::DigitalInput::value         = false;
uint32_t bios::AnalogInputScale::value = 0U;
uint8_t bios::Output::level[2]         = {0U, 0U};
int async::LockType::depth             = 0;

namespace
{
unsigned checks   = 0U;
unsigned failures = 0U;

#define CHECK(c)                                                     \
    do                                                               \
    {                                                                \
        ++checks;                                                    \
        if (!(c))                                                    \
        {                                                            \
            ++failures;                                              \
            std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); \
        }                                                            \
    } while (0)

void cycle()
{
    ::rte::readInputs(0U);
    SensorSwc_Run10ms();
}

void setRaw(uint16_t const current, uint16_t const proxy, uint16_t const kl30b)
{
    bios::AnalogInput::raw[bios::AnalogInput::Ai_SENSE_TSCURRENT]    = current;
    bios::AnalogInput::raw[bios::AnalogInput::Ai_PROXY_ANALOG]       = proxy;
    bios::AnalogInput::raw[bios::AnalogInput::Ai_CURRENTSENSE_KL30B] = kl30b;
}
} // namespace

int main()
{
    ::rte::init();
    CHECK(SensorSwc_TsCurrent == 0); // component not run yet
    SensorSwc_Run10ms();
    CHECK(SensorSwc_TsCurrent == -7); // init value of the port until the first transfer
    CHECK(SensorSwc_TsCurrentQlf == QLF_DEBOUNCE);

    // Values of the synthetic test profile testproject_full (PLAT-62, testboard_full): VREFH 5000 mV, SENSE_TSCURRENT
    // shunt 1 mOhm with gain 50 (20 mA per mV) around 5000 mV / 2, PROXY_ANALOG pull-up 470 ohm from 5000 mV over a
    // 300 mV diode, CURRENTSENSE_KL30B k_ILIS 2000 at 1 kOhm.
    // one conversion per channel, even though value and quality of a channel are both connected
    setRaw(2046U, 3000U, 1000U);
    unsigned const before = bios::AnalogInput::reads;
    cycle();
    CHECK(bios::AnalogInput::reads - before == 3U);
    // raw 2046 -> 2498.2 mV, (2498.2 mV - 2500 mV) * 20 = -36.6 mA -> -37 (signed, rounded half away from zero)
    CHECK(SensorSwc_TsCurrent == -37);
    CHECK(SensorSwc_TsCurrentQlf == QLF_OK);
    // raw 3000 -> 3663 mV: 470 ohm * 3663 / (5000 - 300 - 3663) = 1660 ohm
    CHECK(SensorSwc_Proxy == 1660);
    CHECK(SensorSwc_ProxyQlf == QLF_OK);
    CHECK(SensorSwc_SwitchQlf == QLF_OK);

    setRaw(2048U, 2999U, 1U);
    cycle();
    CHECK(SensorSwc_TsCurrent == 12);
    CHECK(SensorSwc_Proxy == 1658);
    CHECK(SensorSwc_SwitchQlf == QLF_OK);

    // ends of the converter and of the amplifier: value copied, quality QLF_ERROR_RANGE
    setRaw(8U, 4095U, 4095U);
    cycle();
    CHECK(SensorSwc_TsCurrent == -49805);
    CHECK(SensorSwc_TsCurrentQlf == QLF_ERROR_RANGE); // below the 10 mV swing of the amplifier
    CHECK(SensorSwc_Proxy == 6030100);                // no plug: pin at VREFH, beyond the diode drop
    CHECK(SensorSwc_ProxyQlf == QLF_ERROR_RANGE);
    CHECK(SensorSwc_SwitchQlf == QLF_ERROR_RANGE); // IS fault current drives the pin to VREFH

    setRaw(4094U, 0U, 0U);
    cycle();
    CHECK(SensorSwc_TsCurrent == 49976);
    CHECK(SensorSwc_TsCurrentQlf == QLF_OK);
    CHECK(SensorSwc_Proxy == 0);
    CHECK(SensorSwc_ProxyQlf == QLF_ERROR_RANGE);

    // failed conversion: quality QLF_ERROR, the last value stays (a non-zero one, so a zero would show)
    setRaw(4094U, 2999U, 1U);
    cycle();
    CHECK(SensorSwc_Proxy == 1658);
    bios::AnalogInput::failing = true;
    setRaw(2046U, 3000U, 1000U);
    cycle();
    CHECK(SensorSwc_TsCurrent == 49976);
    CHECK(SensorSwc_TsCurrentQlf == QLF_ERROR);
    CHECK(SensorSwc_Proxy == 1658);
    CHECK(SensorSwc_ProxyQlf == QLF_ERROR);
    CHECK(SensorSwc_SwitchQlf == QLF_ERROR);

    // healing with the next good conversion
    bios::AnalogInput::failing = false;
    cycle();
    CHECK(SensorSwc_TsCurrent == -37);
    CHECK(SensorSwc_TsCurrentQlf == QLF_OK);
    CHECK(SensorSwc_Proxy == 1660);

    std::printf("rte_sensor_host_test: %u checks, %u failures\n", checks, failures);
    return (failures == 0U) ? 0 : 1;
}
